import mongoose from 'mongoose';
import { jsonOptions } from './shared/json.js';
import { searchable } from './shared/searchable.js';
import { softDelete } from './shared/softDelete.js';

const { ObjectId } = mongoose.Schema.Types;

const leadSchema = new mongoose.Schema(
  {
    // Generated by the server (see services/sequence.service.js); never accepted from clients.
    leadNumber: { type: String, required: true, unique: true, immutable: true },
    // Both optional: a lead can start before the company or person is on record.
    companyId: { type: ObjectId, ref: 'Company', index: true },
    contactId: { type: ObjectId, ref: 'Contact', index: true },
    title: { type: String, required: true, trim: true, maxlength: 200 },
    description: { type: String, trim: true, maxlength: 5000 },
    sourceId: { type: ObjectId, ref: 'LeadSource', index: true },
    statusId: { type: ObjectId, ref: 'LeadStatus', required: true, index: true },
    priorityId: { type: ObjectId, ref: 'LeadPriority', index: true },
    estimatedValue: { type: Number, min: 0 },
    assignedTo: { type: ObjectId, ref: 'User', index: true },
    expectedCloseDate: { type: Date },
    notes: { type: String, trim: true, maxlength: 5000 },
    tags: [{ type: String, trim: true, maxlength: 30 }],
    organizationId: { type: ObjectId, ref: 'Organization', index: true },
    createdBy: { type: ObjectId, ref: 'User' },

    // Set when the lead is converted. A lead converts once.
    convertedAt: { type: Date, default: null },
    convertedBy: { type: ObjectId, ref: 'User' },
    opportunityId: { type: ObjectId, ref: 'Opportunity' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      omit: ['deletedAt'],
      aliases: {
        companyId: 'company',
        contactId: 'contact',
        sourceId: 'source',
        statusId: 'status',
        priorityId: 'priority',
        assignedTo: 'assignedToUser',
        organizationId: 'organization',
        createdBy: 'createdByUser',
        convertedBy: 'convertedByUser',
        opportunityId: 'opportunity',
      },
    }),
  }
);

leadSchema.virtual('isConverted').get(function isConverted() {
  return Boolean(this.convertedAt);
});

softDelete(leadSchema);

// Found by global search on these fields.
searchable(leadSchema, ['leadNumber', 'title', 'tags']);

export default mongoose.model('Lead', leadSchema);
